exos.sol:
```
let move source destination =
  print_int source ;
  print_string " -> " ;
  print_int destination ;
  print_newline () ;;
let hanoi n =
  let rec play n source destination =
    if n > 0 then
      begin
        let inter = 6 - source - destination in
        play (n - 1) source inter ;
        move source destination ;
        play (n - 1) inter destination
      end
  in
  if n <= 0 then invalid_arg "Hanoi: number of disks invalid"
  else play n 1 3 ;;
```

```
val move : int -> int -> unit = <fun>
val hanoi : int -> unit = <fun>
```

Les piquets valent $1+2+3=6$ : l'intermédiaire est $6-$source$-$destination. $n-1$ disques vers l'intermédiaire, le grand vers la destination, puis les $n-1$ par-dessus.

```
let fibo n =
  let rec fib a b k =
    if k = 0 then a
    else fib b (a + b) (k - 1)
  in
  if n < 0 then invalid_arg "fibo: n < 0"
  else fib 0 1 n ;;
```

```
val fibo : int -> int = <fun>
```

`fib a b k` avance de $k$ termes en partant de $(F_i, F_{i+1})=(a, b)$ : $n+1$ appels au lieu d'un nombre exponentiel.

